def infer_federated_continual_knowledge_representation(*,request_id:str,federation_id:str,peers:Sequence[FederatedKnowledgePeer],min_quorum:int,replay_identity:str,policy_allow:bool=True,protected_closure:bool=True,raw_data_local:bool=True,signed_approval:bool=True)->FederatedKnowledgeReceipt:
    if not request_id.strip() or not federation_id.strip() or not peers or min_quorum<=0 or min_quorum>len(peers) or not re.fullmatch(r"[0-9a-f]{64}",replay_identity) or not raw_data_local: raise ResearchContractError("federated knowledge identity, peer set, quorum, replay, or locality is invalid")
