    if not policy_allow: counter.add("counterexample:policy-denied"); omissions.add("control:policy-denied")
    if not protected_closure: counter.add("counterexample:protected-closure-incomplete"); omissions.add("control:protected-closure-incomplete")
    if unresolved: witnesses.add("gate:partial-peer-results-retained")
    exchange_order=tuple(sorted(exchange)); disposition="denied" if not global_open or denied else "unresolved" if not quorum_met else "partial" if unresolved else "completed"; evidence=research_artifact_digest({"candidate_order":list(ordered),"qualified_order":sorted(qualified),"unresolved_order":sorted(unresolved),"denied_order":sorted(denied)}); provenance=research_artifact_digest({"federation_id":federation_id,"exchange_order":list(exchange_order),"replay_identity":replay_identity}); run=research_artifact_digest({"feature_id":FEDERATED_CONTINUAL_KNOWLEDGE_REPRESENTATION_INFERENCE_ENGINE_FEATURE_ID,"request_id":request_id,"disposition":disposition,"qualified_order":sorted(qualified),"unresolved_order":sorted(unresolved),"denied_order":sorted(denied),"quorum_met":quorum_met,"evidence_digest":evidence,"provenance_digest":provenance,"replay_identity":replay_identity}); artifact={"content_hash":research_artifact_digest({"request_id":request_id,"run_digest":run}),"media_type":"application/vnd.aurora.federated-continual-knowledge-world+json"}; receipt=FederatedKnowledgeReceipt(request_id=request_id,federation_id=federation_id,disposition=disposition,candidate_order=ordered,qualified_order=tuple(sorted(qualified)),unresolved_order=tuple(sorted(unresolved)),denied_order=tuple(sorted(denied)),exchange_order=exchange_order,semantic_profile_order=tuple(sorted(profiles)),freshness_order=tuple(sorted(fresh)),quorum_required=min_quorum,quorum_met=quorum_met,run_digest=run,evidence_digest=evidence,provenance_digest=provenance,replay_identity=replay_identity,witness_order=tuple(sorted(witnesses)),counterexample_order=tuple(sorted(counter)),omissions=tuple(sorted(omissions)),uncertainty=tuple(sorted(uncertainty)),negative_evidence=tuple(sorted(negative)),effect_receipts=(f"read:local-federated-knowledge:{request_id}",) if disposition=="completed" else ("block:unsafe-release",),artifact=artifact,raw_data_local=raw_data_local); receipt.validate(); return receipt
